#!/usr/bin/env python3
import sys, json, re, argparse, os, urllib.request, ssl, uuid
from collections import OrderedDict

RAW_TOKEN = "RAW_" + str(uuid.uuid4())

class RawNumber:
    def __init__(self, val):
        self.val = val

def serialize_raw(o):
    if isinstance(o, RawNumber):
        return f"{RAW_TOKEN}{o.val}{RAW_TOKEN}"
    raise TypeError

def dumps_ungron(obj, sort):
    j = json.dumps(obj, indent=2, sort_keys=sort, default=serialize_raw)
    return re.sub(rf'"{RAW_TOKEN}(.*?){RAW_TOKEN}"', r'\1', j)

def get_args():
    known_flags = {
        'u': 'ungron', 'ungron': 'ungron',
        'v': 'values', 'values': 'values',
        'c': 'colorize', 'colorize': 'colorize',
        'm': 'monochrome', 'monochrome': 'monochrome',
        's': 'stream', 'stream': 'stream',
        'k': 'insecure', 'insecure': 'insecure',
        'x': 'proxy', 'proxy': 'proxy',
        'noproxy': 'noproxy',
        'j': 'json', 'json': 'json',
        'no-sort': 'no_sort',
        'version': 'version'
    }

    new_args = []
    for arg in sys.argv[1:]:
        if arg.startswith('-') and not arg.startswith('--'):
            name = arg[1:]
            if '=' in name:
                k, v = name.split('=', 1)
                if k in known_flags:
                    new_args.append('--' + known_flags[k] + '=' + v)
                else:
                    new_args.append(arg)
            elif name in known_flags:
                new_args.append('--' + known_flags[name])
            else:
                new_args.append(arg)
        elif arg.startswith('--'):
            new_args.append(arg)
        else:
            new_args.append(arg)

    parser = argparse.ArgumentParser(add_help=False)
    parser.add_argument('-u', '--ungron', action='store_true')
    parser.add_argument('-v', '--values', action='store_true')
    parser.add_argument('-c', '--colorize', action='store_true')
    parser.add_argument('-m', '--monochrome', action='store_true')
    parser.add_argument('-s', '--stream', action='store_true')
    parser.add_argument('-k', '--insecure', action='store_true')
    parser.add_argument('-x', '--proxy')
    parser.add_argument('--noproxy')
    parser.add_argument('-j', '--json', action='store_true')
    parser.add_argument('--no_sort', action='store_true')
    parser.add_argument('--no-sort', action='store_true', dest='no_sort')
    parser.add_argument('--version', action='store_true')
    parser.add_argument('args', nargs='*')

    return parser.parse_args(new_args)

def colorize_json(obj, no_sort=False):
    if obj is None: return "\x1b[36mnull\x1b[0m"
    if obj is True: return "\x1b[36mtrue\x1b[0m"
    if obj is False: return "\x1b[36mfalse\x1b[0m"
    if isinstance(obj, RawNumber): return f"\x1b[31m{obj.val}\x1b[0m"
    if isinstance(obj, str):
        esc = json.dumps(obj)[1:-1]
        return f'\x1b[32m"\x1b[0m\x1b[33m{esc}\x1b[0m\x1b[32m"\x1b[0m'
    if isinstance(obj, list):
        if not obj: return "\x1b[35m[\x1b[0m\x1b[35m]\x1b[0m"
        s = "\x1b[35m[\x1b[0m"
        for i, v in enumerate(obj):
            if i > 0: s += "\x1b[1m,\x1b[22m"
            s += colorize_json(v, no_sort)
        s += "\x1b[35m]\x1b[0m"
        return s
    if isinstance(obj, dict):
        if not obj: return "\x1b[35m{\x1b[0m\x1b[35m}\x1b[0m"
        s = "\x1b[35m{\x1b[0m"
        keys = sorted(obj.keys()) if not no_sort else obj.keys()
        for i, k in enumerate(keys):
            if i > 0: s += "\x1b[1m,\x1b[22m"
            k_esc = json.dumps(k)[1:-1]
            s += f'\x1b[34;1m"\x1b[0;22m\x1b[34;1m{k_esc}\x1b[0;22m\x1b[34;1m"\x1b[0;22m'
            s += "\x1b[1m:\x1b[22m"
            s += colorize_json(obj[k], no_sort)
        s += "\x1b[35m}\x1b[0m"
        return s

def format_path(path, color=False):
    if not path: return ""
    p0 = path[0]
    if color:
        s = f"\x1b[34;1m{p0}\x1b[0;22m"
    else:
        s = str(p0)

    for p in path[1:]:
        if isinstance(p, int):
            if color:
                s += f"\x1b[35m[\x1b[0m\x1b[31m{p}\x1b[0m\x1b[35m]\x1b[0m"
            else:
                s += f"[{p}]"
        else:
            if re.match(r'^[a-zA-Z_$][a-zA-Z0-9_$]*$', p):
                if color:
                    s += f".\x1b[34;1m{p}\x1b[0;22m"
                else:
                    s += f".{p}"
            else:
                p_esc = json.dumps(p)
                if color:
                    s += f"\x1b[35m[\x1b[0m\x1b[33m{p_esc}\x1b[0m\x1b[35m]\x1b[0m"
                else:
                    s += f"[{p_esc}]"
    return s

def format_val(val, color=False):
    if val is None: return "\x1b[36mnull\x1b[0m" if color else "null"
    elif val is True: return "\x1b[36mtrue\x1b[0m" if color else "true"
    elif val is False: return "\x1b[36mfalse\x1b[0m" if color else "false"
    elif isinstance(val, RawNumber): return f"\x1b[31m{val.val}\x1b[0m" if color else val.val
    elif isinstance(val, str):
        s = json.dumps(val)
        return f"\x1b[33m{s}\x1b[0m" if color else s
    elif val == {}: return "\x1b[35m{}\x1b[0m" if color else "{}"
    elif val == []: return "\x1b[35m[]\x1b[0m" if color else "[]"
    else:
        s = json.dumps(val)
        return f"\x1b[33m{s}\x1b[0m" if color else s

def format_json_line(path, val, color=False):
    if not color:
        def replace_raw(o):
            if isinstance(o, RawNumber):
                return f"{RAW_TOKEN}{o.val}{RAW_TOKEN}"
            raise TypeError
        j = json.dumps([path, val], separators=(',', ':'), default=replace_raw)
        return re.sub(rf'"{RAW_TOKEN}(.*?){RAW_TOKEN}"', r'\1', j)

    res = "\x1b[35m[\x1b[0m\x1b[35m[\x1b[0m"
    for i, p in enumerate(path):
        if i > 0: res += ","
        if isinstance(p, int): res += f"\x1b[31m{p}\x1b[0m"
        else: res += f"\x1b[33m{json.dumps(p)}\x1b[0m"
    res += "\x1b[35m]\x1b[0m,"

    if val is None: res += "\x1b[36mnull\x1b[0m"
    elif val is True: res += "\x1b[36mtrue\x1b[0m"
    elif val is False: res += "\x1b[36mfalse\x1b[0m"
    elif isinstance(val, RawNumber): res += f"\x1b[31m{val.val}\x1b[0m"
    elif isinstance(val, str): res += f"\x1b[33m{json.dumps(val)}\x1b[0m"
    elif val == {}: res += "\x1b[35m{}\x1b[0m"
    elif val == []: res += "\x1b[35m[]\x1b[0m"
    else: res += f"\x1b[33m{json.dumps(val)}\x1b[0m"

    res += "\x1b[35m]\x1b[0m"
    return res

def walk(obj, path, sort=True):
    if isinstance(obj, dict):
        if not obj:
            yield path, obj
        else:
            yield path, {}
            keys = sorted(obj.keys()) if sort else obj.keys()
            for k in keys:
                yield from walk(obj[k], path + [k], sort)
    elif isinstance(obj, list):
        if not obj:
            yield path, obj
        else:
            yield path, []
            for i, v in enumerate(obj):
                yield from walk(v, path + [i], sort)
    else:
        yield path, obj

def walk_json(obj, path, sort=True):
    yield path, ({} if isinstance(obj, dict) and not obj else ([] if isinstance(obj, list) and not obj else obj))
    if isinstance(obj, dict):
        keys = sorted(obj.keys()) if sort else obj.keys()
        for k in keys:
            yield from walk_json(obj[k], path + [k], sort)
    elif isinstance(obj, list):
        for i, v in enumerate(obj):
            yield from walk_json(v, path + [i], sort)

class _Empty: pass

def merge(path_parts, value, root):
    if len(path_parts) == 0: return value

    def get_type_for(key):
        return list if isinstance(key, int) else dict

    if isinstance(root, _Empty):
        root = get_type_for(path_parts[0])()

    curr = root
    for i, part in enumerate(path_parts[:-1]):
        next_part = path_parts[i+1]
        next_type = get_type_for(next_part)

        if isinstance(curr, dict):
            if part not in curr or not isinstance(curr[part], (dict, list)):
                curr[part] = next_type()
            curr = curr[part]
        elif isinstance(curr, list):
            while len(curr) <= part:
                curr.append(None)
            if not isinstance(curr[part], (dict, list)):
                curr[part] = next_type()
            curr = curr[part]

    last_part = path_parts[-1]
    if isinstance(curr, dict):
        if last_part in curr:
            if type(curr[last_part]) == type(value) and value in ({}, []):
                return root
            if isinstance(curr[last_part], (dict, list)) and not isinstance(value, (dict, list)):
                sys.stderr.write("failed to merge statements: cannot merge object with non-object\n")
                sys.exit(5)
        curr[last_part] = value
    elif isinstance(curr, list):
        while len(curr) <= last_part:
            curr.append(None)
        if type(curr[last_part]) == type(value) and value in ({}, []):
            return root
        if isinstance(curr[last_part], (dict, list)) and not isinstance(value, (dict, list)):
            sys.stderr.write("failed to merge statements: cannot merge array with non-array\n")
            sys.exit(5)
        curr[last_part] = value

    return root

def main():
    args = get_args()
    if getattr(args, 'version', False):
        print("gron version dev")
        sys.exit(0)

    color = sys.stdout.isatty()
    if getattr(args, 'monochrome', False): color = False
    if getattr(args, 'colorize', False): color = True

    if not args.args or args.args[0] == '-':
        f = sys.stdin
    else:
        src = args.args[0]
        if src.startswith("http://") or src.startswith("https://"):
            try:
                req = urllib.request.Request(src, headers={'User-Agent': 'gron/0.1'})
                ctx = ssl.create_default_context()
                if getattr(args, 'insecure', False):
                    ctx.check_hostname = False
                    ctx.verify_mode = ssl.CERT_NONE
                if getattr(args, 'proxy', None):
                    proxy_handler = urllib.request.ProxyHandler({'http': args.proxy, 'https': args.proxy})
                    opener = urllib.request.build_opener(proxy_handler)
                    urllib.request.install_opener(opener)
                resp = urllib.request.urlopen(req, context=ctx)
                f = resp
            except Exception:
                sys.stderr.write("Failed to fetch URL\n")
                sys.exit(4)
        else:
            try:
                f = open(src, 'r')
            except Exception:
                sys.stderr.write(f"open {src}: no such file or directory\n")
                sys.exit(1)

    if getattr(args, 'values', False):
        line_re = re.compile(r'^\s*(?P<path>[a-zA-Z_$][a-zA-Z0-9_$]*(?:(?:\.[a-zA-Z_$][a-zA-Z0-9_$]*)|(?:\[\d+\])|(?:\["(?:\\.|[^"\\])*"\]))*)\s*=\s*(?P<value>null|true|false|-?\d+(?:\.\d+)?(?:[eE][+-]?\d+)?|"(?:\\.|[^"\\])*"|\{\}|\[\])\s*;\s*$')
        for line in f:
            if isinstance(line, bytes): line = line.decode('utf-8')
            line = line.strip()
            if not line or "=" not in line: continue
            m = line_re.match(line)
            if m:
                val_str = m.group("value")
                if val_str in ('{}', '[]'): continue
                if val_str == 'null': print('null')
                elif val_str == 'true': print('true')
                elif val_str == 'false': print('false')
                elif val_str.startswith('"'):
                    print(json.loads(val_str))
                else:
                    print(val_str)
        sys.exit(0)

    if getattr(args, 'ungron', False):
        root = _Empty()
        if getattr(args, 'json', False):
            for line in f:
                if isinstance(line, bytes): line = line.decode('utf-8')
                line = line.strip()
                if not line: continue
                try:
                    arr = json.loads(line, parse_int=RawNumber, parse_float=RawNumber)
                    if not isinstance(arr, list) or len(arr) != 2:
                        sys.stderr.write("invalid JSON layout\n")
                        sys.exit(5)
                except Exception:
                    sys.stderr.write("invalid JSON layout\n")
                    sys.exit(5)

                path = [int(p.val) if isinstance(p, RawNumber) else p for p in arr[0]]
                val = arr[1]
                root = merge(path, val, root)
            if isinstance(root, _Empty):
                sys.stderr.write("unexpected end of JSON input\n")
                sys.exit(5)
            res = root
        else:
            line_re = re.compile(r'^\s*(?P<path>[a-zA-Z_$][a-zA-Z0-9_$]*(?:(?:\.[a-zA-Z_$][a-zA-Z0-9_$]*)|(?:\[\d+\])|(?:\["(?:\\.|[^"\\])*"\]))*)\s*=\s*(?P<value>null|true|false|-?\d+(?:\.\d+)?(?:[eE][+-]?\d+)?|"(?:\\.|[^"\\])*"|\{\}|\[\])\s*;\s*$')
            for line in f:
                if isinstance(line, bytes): line = line.decode('utf-8')
                line = line.strip()
                if not line or "=" not in line: continue
                m = line_re.match(line)
                if not m:
                    sys.stderr.write(f"ungron failed for `{line.split('=')[0].strip()}`: invalid statement\n")
                    sys.exit(5)

                path_str = m.group("path")
                base_m = re.match(r'^([a-zA-Z_$][a-zA-Z0-9_$]*)', path_str)
                path_parts = [base_m.group(1)]
                part_re = re.compile(r'\.([a-zA-Z_$][a-zA-Z0-9_$]*)|\[(\d+)\]|\[("(?:\\.|[^"\\])*")\]')
                for pm in part_re.finditer(path_str[base_m.end():]):
                    if pm.group(1): path_parts.append(pm.group(1))
                    elif pm.group(2): path_parts.append(int(pm.group(2)))
                    elif pm.group(3): path_parts.append(json.loads(pm.group(3)))

                val_str = m.group("value")
                if val_str == 'null': v = None
                elif val_str == 'true': v = True
                elif val_str == 'false': v = False
                elif val_str == '{}': v = {}
                elif val_str == '[]': v = []
                elif val_str.startswith('"'): v = json.loads(val_str)
                else: v = RawNumber(val_str)

                root = merge(path_parts, v, root)

            if isinstance(root, _Empty):
                sys.stderr.write("no statements were parsed\n")
                sys.exit(5)

            if isinstance(root, dict) and len(root) == 1 and "json" in root:
                res = root["json"]
            else:
                res = root

        if color:
            print(colorize_json(res, getattr(args, 'no_sort', False)))
        else:
            print(dumps_ungron(res, not getattr(args, 'no_sort', False)))

        sys.exit(0)

    # Forward mode
    if getattr(args, 'stream', False):
        if getattr(args, 'json', False):
            print(format_json_line([], [], color=color))
        else:
            print(format_path(["json"], color=color) + " = " + format_val([], color=color) + ";")

        i = 0
        for line in f:
            if isinstance(line, bytes): line = line.decode('utf-8')
            line = line.strip()
            if not line: continue
            try:
                obj = json.loads(line, parse_int=RawNumber, parse_float=RawNumber)
                if getattr(args, 'json', False):
                    for path, val in walk_json(obj, [i], not getattr(args, 'no_sort', False)):
                        print(format_json_line(path, val, color=color))
                else:
                    for path, val in walk(obj, ["json", i], not getattr(args, 'no_sort', False)):
                        print(f"{format_path(path, color=color)} = {format_val(val, color=color)};")
            except Exception:
                sys.stderr.write("failed to form statements\n")
                sys.exit(3)
            i += 1
    else:
        content = f.read() if not hasattr(f, 'read') or isinstance(f.read(0), str) else f.read().decode('utf-8')
        if not content.strip():
            sys.stderr.write("failed to form statements: EOF\n")
            sys.exit(3)

        try:
            obj = json.loads(content, parse_int=RawNumber, parse_float=RawNumber)
        except Exception:
            sys.stderr.write("failed to form statements\n")
